package main

import (
	"bufio"
	"fmt"
	"os"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	defer writer.Flush()

	scanner := bufio.NewScanner(reader)
	scanner.Split(bufio.ScanWords)

	var first string
	if !scanner.Scan() {
		return
	}
	first = scanner.Text()

	var s string
	if !scanner.Scan() {
		s = first
	} else {
		s = scanner.Text()
	}

	n := len(s)
	res := n

	for i := 1; i <= n/2; i++ {
		if s[:i] == s[i:2*i] {
			candidate := 1 + n - i
			if candidate < res {
				res = candidate
			}
		}
	}

	fmt.Fprintln(writer, res)
}

